fn pack_mp(values: &[Complex<Float>], poles: i32, slots: usize) -> Result<Vec<u8>> {
    let nc = values.len() / slots;
    let mut out = vec![b' '; 8 * nc * RECORD];
    let zero = Float::new(MP_BITS);
    for slot in 0..4 {
        for m in 0..nc {
            for component in 0..2 {
                let value = if slot < slots && selected(slot, poles) {
                    if component == 0 {
                        &values[m * slots + slot].re
                    } else {
                        &values[m * slots + slot].im
                    }
                } else {
                    &zero
                };
                if !value.is_finite() {
                    return Err("nonfinite QP result".into());
                }
                let text = format!("{value:.39e}");
                if text.len() > RECORD {
                    return Err("QP result exceeds record width".into());
                }
                let offset = (2 * (slot * nc + m) + component) * RECORD;
                out[offset..offset + text.len()].copy_from_slice(text.as_bytes());
            }
        }
    }
    Ok(out)
}

impl LowerExp for Float {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        if f.precision().is_none() {
            f.write_fmt(format_args!(
                "{0:.1$e}",
                self.0,
                (self.0.prec() as f64 * LOG10_2).floor() as usize
            ))
        } else {
            LowerExp::fmt(&self.0, f)
        }
    }
}

impl LowerExp for Float {
    fn fmt(&self, f: &mut Formatter<'_>) -> FmtResult {
        let format = Format {
            exp: ExpFormat::Exp,
            ..Format::default()
        };
        fmt_radix(self, f, format, "")
    }
}

fn fmt_radix(flt: &Float, fmt: &mut Formatter<'_>, format: Format, prefix: &str) -> FmtResult {
    let format = Format {
        precision: fmt.precision(),
        ..format
    };
    let mut s = StringLike::new_malloc();
    big::append_to_string(&mut s, flt, format);
    let st = s.as_str();

pub(crate) fn append_to_string(s: &mut StringLike, f: &Float, format: Format) {
    use core::fmt::Write;

    if f.is_zero() {
        s.push_str(if f.is_sign_negative() { "-0" } else { "0" });
        return;
    }
    if f.is_infinite() {
        s.push_str(match (format.radix > 10, f.is_sign_negative()) {
            (false, false) => "inf",
            (false, true) => "-inf",
            (true, false) => "@inf@",
            (true, true) => "-@inf@",
        });
        return;
    }
    if f.is_nan() {
        s.push_str(match (format.radix > 10, f.is_sign_negative()) {
            (false, false) => "NaN",
            (false, true) => "-NaN",
            (true, false) => "@NaN@",
            (true, true) => "-@NaN@",
        });
        return;
    }

    // no need to add 1 for nul, as req_chars includes an allocation for '.'
    let size = req_chars(f, format, 0);
    s.reserve(size);
    let reserved_ptr = s.as_str().as_ptr();

    let radix_with_case = if format.to_upper {
        -format.radix
    } else {
        format.radix
    };
    let digits = format.precision.unwrap_or(0);
    let mut exp: exp_t;
    unsafe {
        let alloced = s.reserved_space();
        let write_ptr = alloced.as_mut_ptr().cast();
        let mut maybe_exp = MaybeUninit::uninit();
        let c_buf = mpfr::get_str(
            write_ptr,
            maybe_exp.as_mut_ptr(),
            radix_with_case.strict_cast(),
            digits,
            f.as_raw(),
            raw_round(format.round),
        );
        assert_eq!(c_buf, write_ptr);
        exp = maybe_exp.assume_init();
        let c_len = CStr::from_ptr(write_ptr).to_bytes().len();
        // there is also 1 byte for nul character, which will be used for point
        assert!(c_len + 1 < size, "buffer overflow");
        let added_sign = *write_ptr == b'-' as c_char;
        let added_digits = c_len - usize::from(added_sign);
        let digits_before_point = if format.exp == ExpFormat::Exp
            || exp <= 0
            || exp.strict_as::<usize>() > added_digits
        {
            exp = exp.checked_sub(1).expect("overflow");
            1
        } else {
            let e = exp.wrapping_as::<usize>();
            exp = 0;
            e
        };
        let bytes_before_point = digits_before_point + usize::from(added_sign);
        if bytes_before_point == c_len {
            // no point
            s.increase_len(c_len);
        } else {
            let point_ptr = write_ptr.offset(bytes_before_point.strict_as());
            point_ptr.copy_to(point_ptr.offset(1), c_len - bytes_before_point);
            *point_ptr = b'.' as c_char;
            s.increase_len(c_len + 1);
        }
    }
    if format.exp == ExpFormat::Exp || exp != 0 {
        s.push_str(if format.radix > 10 {
            "@"
        } else if format.to_upper {
            "E"
        } else {
            "e"
        });
        write!(s, "{exp}").unwrap();
    }
    debug_assert_eq!(reserved_ptr, s.as_str().as_ptr());
}
